+// L2-006: Inventory Store
+// Durable JSON array with atomic temp+rename persistence
+// Standard library only, no imports
+
+// Define the inventory store
+export function createInventoryStore(filePath) {
+  // Helper to validate item fields
+  function validateItem(item) {
+    if (!item || typeof item !== 'object') {
+      throw new Error('INVALID_ITEM');
+    }
+
+    const { id, name, quantity, unit, price } = item;
+
+    if (!id || typeof id !== 'string' || id.trim() === '') {
+      throw new Error('INVALID_ITEM');
+    }
+
+    if (!name || typeof name !== 'string' || name.trim() === '') {
+      throw new Error('INVALID_ITEM');
+    }
+
+    if (typeof quantity !== 'number' || isNaN(quantity) || quantity < 0) {
+      throw new Error('INVALID_ITEM');
+    }
+
+    if (typeof unit !== 'string' || unit.trim() === '') {
+      throw new Error('INVALID_ITEM');
+    }
+
+    if (typeof price !== 'number' || isNaN(price) || price < 0) {
+      throw new Error('INVALID_ITEM');
+    }
+  }
+
+  // Helper to deep clone an object
+  function deepClone(obj) {
+    return JSON.parse(JSON.stringify(obj));
+  }
+
+  // Helper to check if an item exists
+  function getItem(id) {
+    try {
+      const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
+      return data.find(item => item.id === id);
+    } catch (err) {
+      return null;
+    }
+  }
+
+  // Helper to load the inventory from file
+  function loadInventory() {
+    try {
+      return JSON.parse(fs.readFileSync(filePath, 'utf-8'));
+    } catch (err) {
+      return [];
+    }
+  }
+
+  // Helper to save the inventory to file
+  function saveInventory(data) {
+    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
+  }
+
+  // Helper to create a temporary file
+  function createTempFile(data) {
+    const tempFilePath = filePath + '.tmp';
+    fs.writeFileSync(tempFilePath, JSON.stringify(data, null, 2), 'utf-8');
+    return tempFilePath;
+  }
+
+  // Helper to rename the temporary file to the original file
+  function renameTempFile(tempFilePath) {
+    fs.renameSync(tempFilePath, filePath);
+  }
+
+  // Helper to check if the file exists
+  function fileExists(filePath) {
+    try {
+      fs.accessSync(filePath, fs.constants.F_OK);
+      return true;
+    } catch (err) {
+      return false;
+    }
+  }
+
+  // Helper to create directories if they don't exist
+  function ensureDirectoryExists(filePath) {
+    const dirPath = path.dirname(filePath);
+    if (!fileExists(dirPath)) {
+      fs.mkdirSync(dirPath, { recursive: true });
+    }
+  }
+
+  // Helper to check if the file is corrupted
+  function isCorrupted(filePath) {
+    try {
+      const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
+      if (!Array.isArray(data)) {
+        return true;
+      }
+      return false;
+    } catch (err) {
+      return true;
+    }
+  }
+
+  // Helper to handle errors and return the appropriate status
+  function handleErrors(status) {
+    switch (status) {
+      case 'STATE_CORRUPT':
+        throw new Error('STATE_CORRUPT');
+      case 'INVALID_ITEM':
+        throw new Error('INVALID_ITEM');
+      case 'DUPLICATE_ID':
+        throw new Error('DUPLICATE_ID');
+      case 'NOT_FOUND':
+        throw new Error('NOT_FOUND');
+      case 'INVALID_PATCH':
+        throw new Error('INVALID_PATCH');
+      case 'RANGE':
+        throw new Error('RANGE');
+      default:
+        throw new Error('UNKNOWN_ERROR');
+    }
+  }
+
+  // Create the inventory store
+  const inventory = [];
+
+  // Load the inventory from the file if it exists
+  if (fileExists(filePath)) {
+    const data = loadInventory();
+    if (isCorrupted(filePath)) {
+      handleErrors('STATE_CORRUPT');
+    } else {
+      inventory.push(...data);
+    }
+  }
+
+  // List all items
+  function list() {
+    return deepClone(inventory);
+  }
+
+  // Get an item by ID
+  function get(id) {
+    const item = getItem(id);
+    if (!item) {
+      handleErrors('NOT_FOUND');
+    }
+    return deepClone(item);
+  }
+
+  // Add an item
+  function add(item) {
+    validateItem(item);
+    const existingItem = getItem(item.id);
+    if (existingItem) {
+      handleErrors('DUPLICATE_ID');
+    }
+    inventory.push(item);
+  }
+
+  // Update an item
+  function update(id, patch) {
+    const item = getItem(id);
+    if (!item) {
+      handleErrors('NOT_FOUND');
+    }
+    const updatedItem = { ...item, ...patch };
+    validateItem(updatedItem);
+    const index = inventory.findIndex(i => i.id === id);
+    inventory[index] = updatedItem;
+  }
+
+  // Remove an item
+  function remove(id) {
+    const item = getItem(id);
+    if (!item) {
+      handleErrors('NOT_FOUND');
+    }
+    const index = inventory.findIndex(i => i.id === id);
+    const removedItem = inventory.splice(index, 1)[0];
+    return deepClone(removedItem);
+  }
+
+  // Adjust the quantity of an item
+  function adjust(id, delta) {
+    const item = getItem(id);
+    if (!item) {
+      handleErrors('NOT_FOUND');
+    }
+    if (typeof delta !== 'number' || isNaN(delta) || delta === 0) {
+      handleErrors('INVALID_PATCH');
+    }
+    const newQuantity = item.quantity + delta;
+    if (newQuantity < 0) {
+      handleErrors('RANGE');
+    }
+    item.quantity = newQuantity;
+  }
+
+  // Return the API
+  return {
+    list,
+    get,
+    add,
+    update,
+    remove,
+    adjust
+  };
+}
+
+// Helper functions for file system operations
+const fs = require('fs');
+const path = require('path');

